function GlassKilnBrickTongsMaker.completeMaking(m) local q=1.0+(GlassKilnBrickTongsMaker.getQualityBonus()/100); if GlassKilnBrickTongsMaker.maker then q=q+(GlassKilnBrickTongsMaker.maker.skill/140) end; q=math.min(2.5,q); GlassKilnBrickTongsMaker.productStock[m.productType]=(GlassKilnBrickTongsMaker.productStock[m.productType] or 0)+m.quantity; GlassKilnBrickTongsMaker.totalProducts=GlassKilnBrickTongsMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if GlassKilnBrickTongsMaker.maker then GlassKilnBrickTongsMaker.maker.itemsMade=GlassKilnBrickTongsMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then GlassKilnBrickTongsMaker.maker.skill=math.min(100,GlassKilnBrickTongsMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Klešče izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"glasskilnbricktongs.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function GlassKilnBrickTongsMaker.update(dt) if not _G.state then return end; GlassKilnBrickTongsMaker.dayTimer=GlassKilnBrickTongsMaker.dayTimer+dt; if GlassKilnBrickTongsMaker.dayTimer>=30 then GlassKilnBrickTongsMaker.dayTimer=0; for i=#GlassKilnBrickTongsMaker.activeMaking,1,-1 do local m=GlassKilnBrickTongsMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then GlassKilnBrickTongsMaker.completeMaking(m); table.remove(GlassKilnBrickTongsMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(GlassKilnBrickTongsMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if GlassKilnBrickTongsMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
